/* Minimal self-contained HLS fallback shim for browsers without MSE (docs/DESIGN.md §9 & PROTOCOLS §1). */
(function (global) {
  "use strict";

  function EkranHlsFallback() {}

  EkranHlsFallback.isSupported = function () {
    var v = document.createElement("video");
    return !!(v.canPlayType && (
      v.canPlayType("application/vnd.apple.mpegurl") !== "" ||
      v.canPlayType("application/x-mpegURL") !== ""
    ));
  };

  EkranHlsFallback.prototype.attach = function (videoEl, url) {
    videoEl.src = url;
    return videoEl.play();
  };

  global.EkranHlsFallback = EkranHlsFallback;
})(window);
